        <input type="text" class="otp-input" maxlength="1" inputmode="numeric" autocomplete="one-time-code" data-index="5" dir="ltr">
      </div>

      <div class="error-message" id="error-msg"></div>

      <button type="submit" class="btn" id="verify-btn">تحقق</button>
    </form>

    <div class="countdown" id="countdown">
      <span>إعادة الإرسال بعد </span><span class="time" id="time">0:45</span>
