<script>
  const inputs = document.querySelectorAll('.otp-input');
  const verifyBtn = document.getElementById('verify-btn');
  const countdownEl = document.getElementById('countdown');
  const timeEl = document.getElementById('time');
  const resendLink = document.getElementById('resend-link');
  const errorMsg = document.getElementById('error-msg');
  const form = document.querySelector('.otp-form');

  let countdown = 45;
  let countdownTimer = null;

  // Auto-focus first input
  inputs[0].focus();

  // Handle input movement between boxes
  inputs.forEach((input, index) => {
    input.addEventListener('input', () => {
      errorMsg.textContent = '';
      input.classList.remove('error');
      if (input.value.length === 1) {
        if (index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
      }
    });

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Backspace' && input.value === '' && index > 0) {
        inputs[index - 1].focus();
      }
    });

    input.addEventListener('paste', (e) => {
      e.preventDefault();
      const pasted = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 6);
      pasted.split('').forEach((char, i) => {
        if (inputs[i]) {
          inputs[i].value = char;
        }
      });
      const next = Math.min(pasted.length, 5);
      inputs[next]?.focus();
    });
  });

  // Start countdown
  function startCountdown() {
    countdown = 45;
    resendLink.classList.add('disabled');
    resendLink.textContent = 'لم تصل الرمز؟';
    countdownEl.style.display = 'block';
    timeEl.textContent = formatTime(countdown);

    if (countdownTimer) clearInterval(countdownTimer);
    countdownTimer = setInterval(() => {
      countdown--;
      timeEl.textContent = formatTime(countdown);
      if (countdown <= 0) {
        clearInterval(countdownTimer);
        countdownTimer = null;
        resendLink.classList.remove('disabled');
        resendLink.textContent = 'أعد الإرسال';
      }
    }, 1000);
  }

  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return mins + ':' + (secs < 10 ? '0' + secs : secs);
  }

  // Verify code
  function verifyCode() {
    const code = Array.from(inputs).map(i => i.value).join('');
    if (code.length < 6) {
      showError('الرجاء إ Entered الرمز الكامل المكون من 6 أرقام');
      return false;
    }
    // Simulate verification
    verifyBtn.disabled = true;
    verifyBtn.textContent = 'جاري التحقق...';
    setTimeout(() => {
      verifyBtn.disabled = false;
      verifyBtn.textContent = 'تحقق';
      showError('الرمز غير صحيح، يرجاء المحاولة مرة أخرى');
      inputs.forEach(i => i.value = '');
      inputs[0].focus();
    }, 1500);
    return false;
  }

  function showError(msg) {
    errorMsg.textContent = msg;
    inputs.forEach(i => i.classList.add('error'));
  }

  // Resend
  resendLink.addEventListener('click', (e) => {
    if (resendLink.classList.contains('disabled')) {
      e.preventDefault();
      return;
    }
    e.preventDefault();
    startCountdown();
    inputs.forEach(i => i.value = '');
    inputs[0].focus();
  });

  // Start countdown on load
  startCountdown();
</script>
</body>
</html>
